import * as THREE from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load texture via cached context loader
  const texture = ctx.textureLoader.load(config.assets.imageUrl);

  // Calculate plane dimensions from atlas region aspect ratio
  const atlasRegion = config.atlasRegion || { width: 512, height: 320 };
  const aspectRatio = atlasRegion.width / atlasRegion.height;

  // Create plane geometry scaled by aspect ratio
  const geometry = new THREE.PlaneGeometry(aspectRatio, 1);

  // Static textured plane material
  const material = new THREE.MeshBasicMaterial({
    map: texture,
    transparent: true,
    side: THREE.DoubleSide,
  });

  // Create and add mesh to group
  const mesh = new THREE.Mesh(geometry, material);

  // Apply scene transform
  const pos = config.scenePosition || {};
  mesh.position.set(pos.x ?? 0, pos.y ?? 0, pos.z ?? 0);

  if (pos.rotationXYZ && Array.isArray(pos.rotationXYZ)) {
    mesh.rotation.order = 'XYZ';
    mesh.rotation.x = pos.rotationXYZ[0] ?? 0;
    mesh.rotation.y = pos.rotationXYZ[1] ?? 0;
    mesh.rotation.z = pos.rotationXYZ[2] ?? 0;
  }

  if (pos.scaleXYZ && Array.isArray(pos.scaleXYZ)) {
    mesh.scale.set(pos.scaleXYZ[0] ?? 1, pos.scaleXYZ[1] ?? 1, pos.scaleXYZ[2] ?? 1);
  }

  group.add(mesh);

  // Event handlers
  group.userData.handlers = {};

  // Resource cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
  };

  return group;
}
